// Angular testing environment setup
import 'zone.js'
import 'zone.js/testing'
import { getTestBed } from '@angular/core/testing'
import {
  BrowserDynamicTestingModule,
  platformBrowserDynamicTesting,
} from '@angular/platform-browser-dynamic/testing'
import '@angular/compiler'

// Add global test helper
;(global as any).fail = (message?: string) => {
  throw new Error(message || 'Test failed')
}

// Angular production mode
process.env.NODE_ENV = 'production'

// Reset test environment
try {
  getTestBed().resetTestEnvironment()
} catch (e) {
  console.warn('Error resetting the test environment:', e)
}

// Initialize testing platform
getTestBed().initTestEnvironment(
  BrowserDynamicTestingModule,
  platformBrowserDynamicTesting(),
  { teardown: { destroyAfterEach: true } }
)

// Browser mocks
Object.defineProperty(window, 'CSS', { value: null })
Object.defineProperty(window, 'getComputedStyle', {
  value: () => ({
    display: 'none',
    appearance: ['-webkit-appearance'],
    getPropertyValue: () => '',
  }),
})
Object.defineProperty(document, 'doctype', { value: '<!DOCTYPE html>' })
Object.defineProperty(document.body.style, 'transform', {
  value: () => ({ enumerable: true, configurable: true }),
})
